# Terraform Refactor: Modules + `for_each` with Zero-Diff State Moves

## Starting Point: Duplicated Blocks

```hcl
# main.tf (BEFORE — duplicated dev/prod)

resource "aws_eks_cluster" "dev" {
  name     = "app-dev"
  role_arn = aws_iam_role.eks_cluster_dev.arn
  version  = "1.29"

  vpc_config {
    subnet_ids = aws_subnet.dev[*].id
  }
}

resource "aws_eks_node_group" "dev" {
  cluster_name    = aws_eks_cluster.dev.name
  node_group_name = "app-dev"
  node_role_arn   = aws_iam_role.eks_nodes_dev.arn
  subnet_ids      = aws_subnet.dev[*].id
  instance_types  = ["t3.medium"]

  scaling_config {
    desired_size = 2
    min_size     = 2
    max_size     = 2
  }
}

resource "aws_eks_cluster" "prod" {
  name     = "app-prod"
  role_arn = aws_iam_role.eks_cluster_prod.arn
  version  = "1.29"

  vpc_config {
    subnet_ids = aws_subnet.prod[*].id
  }
}

resource "aws_eks_node_group" "prod" {
  cluster_name    = aws_eks_cluster.prod.name
  node_group_name = "app-prod"
  node_role_arn   = aws_iam_role.eks_nodes_prod.arn
  subnet_ids      = aws_subnet.prod[*].id
  instance_types  = ["t3.large"]

  scaling_config {
    desired_size = 4
    min_size     = 4
    max_size     = 4
  }
}

resource "aws_s3_bucket" "dev" {
  bucket = "app-assets-dev"
}

resource "aws_s3_bucket_versioning" "dev" {
  bucket = aws_s3_bucket.dev.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "dev" {
  bucket = aws_s3_bucket.dev.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "dev" {
  bucket                  = aws_s3_bucket.dev.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket" "prod" {
  bucket = "app-assets-prod"
}

resource "aws_s3_bucket_versioning" "prod" {
  bucket = aws_s3_bucket.prod.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "prod" {
  bucket = aws_s3_bucket.prod.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "prod" {
  bucket                  = aws_s3_bucket.prod.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_replication_configuration" "prod" {
  bucket = aws_s3_bucket.prod.id
  role   = aws_iam_role.replication_prod.arn

  rule {
    id     = "replicate-to-west"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.prod_replica.arn
      storage_class = "STANDARD"
    }
  }
}

resource "aws_db_instance" "dev" {
  identifier             = "app-dev"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  multi_az               = false
  publicly_accessible    = false
  deletion_protection    = true
  backup_retention_period = 7
  skip_final_snapshot    = false
  final_snapshot_identifier = "app-dev-final"
  db_name                = "app"
  username               = var.db_username_dev
  password               = var.db_password_dev
}

resource "aws_db_instance" "prod" {
  identifier             = "app-prod"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t3.medium"
  allocated_storage      = 100
  multi_az               = true
  storage_encrypted      = true
  publicly_accessible    = false
  deletion_protection    = true
  backup_retention_period = 14
  skip_final_snapshot    = false
  final_snapshot_identifier = "app-prod-final"
  db_name                = "app"
  username               = var.db_username_prod
  password               = var.db_password_prod
}

# ... similarly duplicated IAM, ACM, CloudFront, Secrets blocks
```

