### `modules/environment/iam.tf`

```hcl
# Service account IAM user (dev: programmatic, prod: OIDC role)

resource "aws_iam_user" "app" {
  count = var.iam_oidc_trust ? 0 : 1
  name  = "app-${var.env_name}"
}

resource "aws_iam_access_key" "app" {
  count = var.iam_oidc_trust ? 0 : 1
  user  = aws_iam_user.app[0].name
}

resource "aws_iam_role" "app" {
  name = "app-${var.env_name}-role"

  assume_role_policy = var.iam_oidc_trust ? jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Federated = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${replace(aws_eks_cluster.this.identity[0].oidc[0].issuer, "https://", "")}"
      }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringEquals = {
          "${replace(aws_eks_cluster.this.identity[0].oidc[0].issuer, "https://", "")}:sub" = "system:serviceaccount:default:app-${var.env_name}"
        }
      }
    }]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { AWS = aws_iam_user.app[0].arn }
    }]
  })
}

# Least-privilege: scoped to the specific bucket, no wildcards on prod
resource "aws_iam_role_policy" "app_s3" {
  name = "app-${var.env_name}-s3-access"
  role = aws_iam_role.app.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BucketAccess"
        Effect = "Allow"
        Action = var.env_name == "prod" ? [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
        ] : [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
        ]
        Resource = [
          aws_s3_bucket.assets.arn,
          "${aws_s3_bucket.assets.arn}/*",
        ]
      }
    ]
  })
}

data "aws_caller_identity" "current" {}
```

### `modules/environment/https.tf`

```hcl
# CloudFront + ACM (prod) or internal ALB placeholder (dev)

resource "aws_acm_certificate" "this" {
  count             = var.https_exposure == "cloudfront" ? 1 : 0
  domain_name       = var.domain_name
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Environment = var.env_name
  }
}

resource "aws_cloudfront_distribution" "this" {
  count   = var.https_exposure == "cloudfront" ? 1 : 0
  enabled = true

  origin {
    domain_name = aws_s3_bucket.assets.bucket_regional_domain_name
    origin_id   = "s3-assets"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.this[0].cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "s3-assets"
    viewer_protocol_policy = "https-only"

    forwarded_values {
      query_string = false
      cookies { forward = "none" }
    }
  }

  viewer_certificate {
    acm_certificate_arn      = aws_acm_certificate.this[0].arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  aliases = var.domain_name != null ? [var.domain_name] : []

  tags = {
    Environment = var.env_name
  }
}

resource "aws_cloudfront_origin_access_identity" "this" {
  count   = var.https_exposure == "cloudfront" ? 1 : 0
  comment = "OAI for ${var.bucket_name}"
}
```

### `modules/environment/secrets.tf`

```hcl
# DB connection string stored in AWS Secrets Manager
# The plaintext value comes from a SOPS-encrypted .tfvars file, never committed to Git

resource "aws_secretsmanager_secret" "db_connection" {
  name        = "app-${var.env_name}-db-connection"
  description = "PostgreSQL connection string for ${var.env_name}"

  tags = {
    Environment = var.env_name
  }
}

resource "aws_secretsmanager_secret_version" "db_connection" {
  secret_id = aws_secretsmanager_secret.db_connection.id
  secret_string = jsonencode({
