## Step 3: Root Module with `for_each`

```hcl
# main.tf (AFTER — refactored)

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    sops = {
      source  = "carlpett/sops"
      version = "~> 1.0"
    }
  }

  backend "s3" {
    bucket         = "terraform-state-app"
    key            = "infrastructure/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}

provider "aws" {
  region = "us-east-1"
}

# Alias provider for cross-region replication target
provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

# SOPS-encrypted secrets (never plaintext in Git)
data "sops_file" "secrets" {
  for_each    = local.environments
  source_file = "secrets/${each.key}.enc.yaml"
}

module "environment" {
  for_each = local.environments

  source = "./modules/environment"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  env_name            = each.key
  region              = each.value.region
  cluster_name        = each.value.cluster_name
  node_instance_types = each.value.node_instance_types
  node_count          = each.value.node_count
  bucket_name         = each.value.bucket_name
  enable_replication  = each.value.enable_replication
  replica_region      = each.value.replica_region
  db_instance_class   = each.value.db_instance_class
  db_multi_az         = each.value.db_multi_az
  db_storage          = each.value.db_storage
  db_encrypted        = each.value.db_encrypted
  db_backup_retention = each.value.db_backup_retention
  db_identifier       = each.value.db_identifier
  db_username         = data.sops_file.secrets[each.key].data["db_username"]
  db_password         = data.sops_file.secrets[each.key].data["db_password"]
  https_exposure      = each.value.https_exposure
  domain_name         = each.value.domain_name
  iam_oidc_trust      = each.value.iam_oidc_trust
}
```

## Step 4: Zero-Diff State Migration

The critical step. Every existing resource address must be moved to its new module address **before** running `plan`.

### State Move Script

```bash
#!/usr/bin/env bash
# migrate-state.sh — Run ONCE before first `terraform plan` after refactor
#
# Maps every old top-level resource address to its new module address.
# After running this, `terraform plan` must show zero changes.

set -euo pipefail

ENVS=("dev" "prod")

for env in "${ENVS[@]}"; do
  MODULE="module.environment[\"${env}\"]"

  # --- EKS ---
  terraform state mv \
    "aws_eks_cluster.${env}" \
    "${MODULE}.aws_eks_cluster.this"

  terraform state mv \
    "aws_eks_node_group.${env}" \
    "${MODULE}.aws_eks_node_group.this"

  terraform state mv \
    "aws_iam_role.eks_cluster_${env}" \
    "${MODULE}.aws_iam_role.eks_cluster"

